  const passes = results.passes.length;

  console.log('=== Accessibility Test Results ===');
  console.log('Passes:', passes);
  console.log('WCAG Violations:', wcag.length);
  console.log('Best Practice Warnings:', bp.length);

  if (wcag.length > 0) {
    console.log('\nWCAG Issues:');
    wcag.forEach(v => {
      console.log(`  - ${v.id} (${v.impact}): ${v.nodes.map(n => n.target).join(', ')}`);
    });
  }

  if (bp.length > 0) {
    console.log('\nBest Practice Warnings:');
    bp.forEach(v => {
      console.log(`  - ${v.id}: ${v.nodes.map(n => n.target).join(', ')}`);
    });
  }

  console.log('\n=== Test Status ===');
  console.log(wcag.length === 0 ? '✓ PASS - No WCAG violations' : '✗ FAIL - WCAG violations found');

  await browser.close();
  process.exit(wcag.length > 0 ? 1 : 0);
})();
